const sme = $('Normalize SME Profile From Body').first().json;
const rows = $input.all().map(item => item.json);

const activeRows = rows.filter(r => {
  const val = String(r.active ?? "").toLowerCase().trim();
  return val === "true" || val === "yes" || val === "1" || val === "active";
});

function normalize(value) {
  return String(value ?? "")
    .toLowerCase()
    .trim()
    .replace(/\s+/g, " ");
}

function splitTags(value) {
  if (!value) return [];
  return String(value)
    .split(/[;,]/)
    .map(v => v.trim())
    .filter(Boolean);
}

function alias(value) {
  const v = normalize(value);

  const map = {
    "any": "any",
    "all": "any",
    "all smes": "any",
    "universal": "any",
    "always": "any",

    "northamerica": "north america",
    "north america": "north america",
    "latam": "latam",
    "eastern europe": "eastern europe",
    "middle east": "middle east",
    "south asia": "south asia",
    "uk": "uk",
    "eu": "eu",
    "apac": "apac",
    "oceania": "oceania",
    "africa": "africa",

    "manufacturing": "manufacturing (industrial / components)",
    "manufacturing (industrial / components)": "manufacturing (industrial / components)",
    "food & agro-processing": "food & agro-processing",
    "food and agro-processing": "food & agro-processing",
    "consumer goods": "consumer goods (apparel / fmcg)",
    "consumer goods (apparel / fmcg)": "consumer goods (apparel / fmcg)",
    "construction / materials": "construction / materials",
    "construction and materials": "construction / materials",
    "business / export services": "business / export services",
    "business and export services": "business / export services"
  };

  return map[v] || v;
}

function splitMulti(value) {
  if (!value) return [];
  if (Array.isArray(value)) {
    return value.map(v => alias(v)).filter(Boolean);
  }
  return String(value)
    .split(/[;,]/)
    .map(v => alias(v))
    .filter(Boolean);
}

function employeeBandRank(value) {
  const canonical = String(value ?? "")
    .toLowerCase()
    .replace(/[–—]/g, "-")
    .replace(/\s*-\s*/g, "-")
    .replace(/,/g, "")
    .replace(/\s+/g, " ")
    .trim();

  const ranks = {
    "1-10": 1,
    "11-50": 2,
    "51-250": 3,
    "251-500": 4,
    "501-1000": 5,
    "1001+": 6
  };

  return ranks[canonical] || null;
}

function matchesSize(row, sme) {
  const size = normalize(row.size_applicability || row.size_relevance || "all");
  const rank = employeeBandRank(sme.employee_band);

  if (!size || size === "all" || size === "all smes") return true;

  if (size === "medium_plus") {
    if (!rank) return false;
    return rank >= 3;
  }

  if (size === "large") {
    if (!rank) return false;
    return rank >= 5;
  }

  return true;
}

function matchesNewTriggers(row, sme) {
  const industryTrigger = alias(row.industry_trigger || "ANY");
  const marketTrigger = alias(row.market_trigger || "ANY");

  const smeIndustry = alias(sme.industry);
  const smeMarkets = [
  ...splitMulti(sme.target_market_region),
  alias(sme.company_location)
].filter(Boolean);

  const triggerIndustries = industryTrigger
    ? String(industryTrigger).split(/[;,]/).map(v => alias(v)).filter(Boolean)
    : ['any'];
  const industryOk =
    triggerIndustries.includes('any') ||
    triggerIndustries.includes(smeIndustry);

  const triggerMarkets = marketTrigger
    ? String(marketTrigger).split(/[;,]/).map(v => alias(v)).filter(Boolean)
    : ['any'];
  const marketOk =
    triggerMarkets.includes('any') ||
    triggerMarkets.some(t => smeMarkets.includes(t));

  return industryOk && marketOk && matchesSize(row, sme);
}

const selected = activeRows
  .filter(row => matchesNewTriggers(row, sme))
  .map(row => ({
    question_id: row.question_id,
    question_text: row.question_text,
    question_type: row.question_type,
    trigger_value: row.trigger_value,
    industry_trigger: row.industry_trigger,
    market_trigger: row.market_trigger,
    framework_source: row.framework_source,
    base_weight: row.base_weight,
    priority: row.priority,
    active: row.active,
    tags: splitTags(row.tags),
    answer_scale_id: row.answer_scale_id,
    response_type: row.response_type,
    metric_id: row.metric_id,
    category: row.category,
    subcategory: row.subcategory,
    rationale: row.rationale,
    cluster_id: row.cluster_id,
    size_applicability: row.size_applicability,
    cluster_progression_level: row.cluster_progression_level
  }));

selected.sort((a, b) => {
  const pa = Number(a.priority ?? 999999);
  const pb = Number(b.priority ?? 999999);
  return pa - pb;
});

return [
  {
    json: {
      debug_sme_seen_by_select: sme,
      debug_employee_band_raw: sme.employee_band,
      debug_employee_band_rank: employeeBandRank(sme.employee_band),
      debug_size_counts: {
        all: selected.filter(q => normalize(q.size_applicability || "all") === "all").length,
        medium_plus: selected.filter(q => normalize(q.size_applicability) === "medium_plus").length,
        large: selected.filter(q => normalize(q.size_applicability) === "large").length
      },
      question_count: selected.length,
      selected_questions: selected
    }
  }
];

const input = $input.first().json;

let body = input.body || {};
if (typeof body === "string") {
  body = JSON.parse(body);
}

const sme = body.sme_context || {};

return [{
  json: {
    test_id: null,
    company_name: sme.company_name ?? null,
    industry: sme.industry ?? null,
    subindustry: sme.subindustry ?? null,
    employee_band: sme.employee_band ?? null,
    revenue_band: sme.revenue_band ?? null,
    company_location: sme.company_location ?? null,
    country: sme.country ?? null,
    target_market_region: Array.isArray(sme.target_market_region)
      ? sme.target_market_region
      : sme.target_market_region
        ? [sme.target_market_region]
        : [],
    target_buyer: sme.target_buyer ?? null,
    business_goal: sme.business_goal ?? null,
    notes: sme.notes ?? null
  }
}];
